import json
def card_losses(path):
    counts = {}
    with open(path, encoding="utf-8") as source:
        for line in source:
            if not line.strip():
                continue
            row = json.loads(line)
            if row.get("derived") == "LOSS" and row.get("dry_run") is False:
                for card in set(row.get("opp_cards", [])):
                    counts[card] = counts.get(card,0) + 1
    return counts
